def fill_enclosed_with_different_color(grid, boundary_val=8, fill_val=4):
    result = [[grid[r][c] for c in range(len(row))] for r in range(len(grid))]

    # Find enclosed regions using flood fill
    h = len(grid)
    w = len(grid[0])

    visited = [[False]*w for _ in range(h)]

    # Start BFS from all edges - traverse non-boundary cells
    import collections
    queue = []
    for r in range(h):
        for c in range(w):
            if r == 0 or r == h-1 or c == 0 or c == w-1:
                queue.append((r,c))
                visited[r][c] = True

    q = collections.deque(queue)
    while q:
        r, c = q.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                # Treat boundary value as wall
                if grid[nr][nc] != boundary_val:
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # Fill unvisited non-boundary cells with fill_val
    for r in range(h):
        for c in range(w):
            if not visited[r][c] and grid[r][c] != boundary_val:
                result[r][c] = fill_val

    return result

