# Fill only the truly enclosed component with 4
def fill_enclosed_properly(grid):
    h = len(grid)
    w = len(grid[0])

    # Find all non-8 cells and their connected components
    visited = [[False]*w for _ in range(h)]
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    import collections

    for r in range(h):
        for c in range(w):
            if not visited[r][c] and grid[r][c] != 8:
                # Start BFS for this component
                comp_cells = []
                queue = collections.deque([(r, c)])
                visited[r][c] = True

                while queue:
                    cr, cc = queue.popleft()
                    comp_cells.append((cr, cc))

                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            if grid[nr][nc] != 8:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Check if enclosed (doesn't touch border)
                enclosed = not any(cr == 0 or cr == h-1 or cc == 0 or cc == w-1 for cr, cc in comp_cells)

                if enclosed:
                    # Fill with 4
                    for cr, cc in comp_cells:
                        result[cr][cc] = 4
                    print(f"Filled component of {len(comp_cells)} cells")

    return result

